from __future__ import annotations

from datetime import date, datetime, timedelta

_MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_DOW_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}


def _parse_value(text: str, minimum: int, maximum: int, names: dict[str, int]) -> int:
    """Parse one numeric or named value, checking it is in range."""
    name = text.upper()
    if name in names:
        return names[name]
    if text.isascii() and text.isdigit():
        value = int(text)
        if minimum <= value <= maximum:
            return value
        raise ValueError(f"value {text!r} is outside {minimum}-{maximum}")
    raise ValueError(f"invalid value {text!r}")


def _parse_step(text: str) -> int:
    """Parse the ``S`` in an ``/S`` suffix."""
    if text.isascii() and text.isdigit() and int(text) > 0:
        return int(text)
    raise ValueError(f"invalid step {text!r}")


def _parse_item(
    item: str, minimum: int, maximum: int, names: dict[str, int]
) -> range:
    """Parse one comma-separated item into the range of values it covers."""
    if "/" in item:
        parts = item.split("/")
        if len(parts) != 2:
            raise ValueError(f"invalid item {item!r}")
        base, step = parts[0], _parse_step(parts[1])
    else:
        base, step = item, None

    if base == "*":
        start, end = minimum, maximum
    elif "-" in base:
        bounds = base.split("-")
        if len(bounds) != 2:
            raise ValueError(f"invalid item {item!r}")
        start = _parse_value(bounds[0], minimum, maximum, names)
        end = _parse_value(bounds[1], minimum, maximum, names)
        if start > end:
            raise ValueError(f"range {base!r} ends before it starts")
    else:
        start = _parse_value(base, minimum, maximum, names)
        if step is None:
            end = start
        else:
            end = maximum

    return range(start, end + 1, step if step is not None else 1)


def _parse_field(
    field: str, minimum: int, maximum: int, names: dict[str, int]
) -> set[int]:
    """Parse a whole field, which is a comma-separated list of items."""
    values: set[int] = set()
    for item in field.split(","):
        values.update(_parse_item(item, minimum, maximum, names))
    return values


def _parse(
    expression: str,
) -> tuple[set[int], set[int], set[int], set[int], set[int], bool, bool]:
    """Parse an expression into value sets and day-field restriction flags."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"expected five fields, got {len(fields)}")

    minute, hour, day, month, weekday = fields
    minutes = _parse_field(minute, 0, 59, {})
    hours = _parse_field(hour, 0, 23, {})
    days = _parse_field(day, 1, 31, {})
    months = _parse_field(month, 1, 12, _MONTH_NAMES)
    weekdays = _parse_field(weekday, 0, 7, _DOW_NAMES)
    # 7 is Sunday just like 0, so fold it into 0.
    weekdays = {0 if value == 7 else value for value in weekdays}

    return minutes, hours, days, months, weekdays, day != "*", weekday != "*"


def _add_years(moment: datetime, years: int) -> datetime:
    """``moment`` moved forward by whole calendar years, clamping Feb 29."""
    try:
        return moment.replace(year=moment.year + years)
    except ValueError:
        return moment.replace(year=moment.year + years, day=28)


def _day_matches(
    day: date,
    months: set[int],
    days: set[int],
    weekdays: set[int],
    day_restricted: bool,
    weekday_restricted: bool,
) -> bool:
    """Whether a calendar day matches the date fields."""
    if day.month not in months:
        return False

    day_match = day.day in days
    # datetime.weekday() is Monday=0..Sunday=6; cron is Sunday=0..Saturday=6.
    weekday_match = (day.weekday() + 1) % 7 in weekdays

    if day_restricted and weekday_restricted:
        return day_match or weekday_match
    return day_match and weekday_match


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    minutes, hours, days, months, weekdays, day_restricted, weekday_restricted = (
        _parse(expression)
    )

    # Matching times have zero seconds and microseconds, so the earliest
    # possible match is the start of the next minute.
    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = _add_years(after, 5)

    day = start.date()
    while day <= limit.date():
        if _day_matches(
            day, months, days, weekdays, day_restricted, weekday_restricted
        ):
            for hour in sorted(hours):
                for minute in sorted(minutes):
                    candidate = datetime(day.year, day.month, day.day, hour, minute)
                    if candidate > after and candidate <= limit:
                        return candidate
        day += timedelta(days=1)

    raise ValueError(f"no run of {expression!r} within five years after {after!r}")

